class Solution {
    private int n;

    public ListNode removeNthFromEnd(ListNode head, int n) {
        this.n = n;
        ListNode dummy = new ListNode(0, head);
        rec(dummy);
        return dummy.next;
    }

    // 返回 node 是倒数第几个
    private int rec(ListNode node) {
        if (node == null) {
            return 0;
        }
        int k = rec(node.next) + 1;
        if (k == n + 1) {
            node.next = node.next.next;
        }
        return k;
    }
}

