build(a, snap) {
    const v = ["D", ...a.v], len = v.length, n = a.n, next = v.map((_, i) => (i + 1 < len ? i + 1 : null));
    let slow = 0, fast = 0, del = -1, gone = false;
    const view = (opts = {}) => [{
      t: "list",
      label: "链表（D 是哑节点；虚红线 × 表示断开的旧指针，高亮箭头表示新接上的指针）",
      nodes: v.map((x, i) => ({
        v: x,
        cls: i === del ? (gone ? "d" : "w") : i === slow ? "a" : i === fast ? "b" : i === 0 ? "d" : "",
        ...(opts.hot === i ? { ecls: "on" } : {}),
        ...(gone && i === del ? { noNil: true } : {}),
      })),
      next: next.slice(),
      ptrs: { slow, fast },
      ...(opts.ghostEdges ? { ghostEdges: opts.ghostEdges } : {}),
      ...(opts.animEdges ? { animEdges: opts.animEdges } : {}),
    }];
    snap("初始化", `在头节点前面加一个哑节点 D，slow 和 fast 都从 D 出发，目标是删掉倒数第 ${n} 个。`, view(), { at: "init", facts: [["目标", `倒数第 ${n} 个`], ["fast 领先步数", 0]] });
    for (let t = 0; t < n; t++) {
      fast++;
      snap("fast 先走", `fast 先往后走第 ${t + 1} 步，来到 <b>${v[fast]}</b>。`, view(), { at: "ahead", facts: [["目标", `倒数第 ${n} 个`], ["fast 领先步数", t + 1, t]] });
    }
    snap("拉开距离", `fast 比 slow 正好领先 ${n} 步。接下来检查 fast.next，两个指针保持间距一起走。`, view(), { at: "loop", facts: [["目标", `倒数第 ${n} 个`], ["fast 领先步数", n]] });
    while (next[fast] !== null) {
      slow++;
      fast++;
      snap("一起走", `fast.next 不为空，slow 前移到 <b>${v[slow]}</b>，fast 前移到 <b>${v[fast]}</b>，间距仍是 ${n}。`, view(), { at: "walk", facts: [["目标", `倒数第 ${n} 个`], ["fast 领先步数", n]] });
    }
    del = slow + 1;
    snap("找到待删节点", `fast 停在最后一个节点 ${v[fast]}（fast.next 为空）。slow 后面的 <b>${v[del]}</b> 正好是倒数第 ${n} 个。`, view(), { at: "loop", facts: [["目标", `倒数第 ${n} 个`], ["待删节点", v[del]]] });
    const newNext = del + 1 < len ? del + 1 : null;
    next[slow] = newNext;
    next[del] = null;
    gone = true;
    snap(
      "绕过并删除",
      `断开 ${v[slow]} → ${v[del]}，把 slow.next 改指 ${newNext === null ? "空（∅）" : `<b>${v[newNext]}</b>`}，${v[del]} 就脱离链表了。`,
      view({ ghostEdges: [[slow, del]], animEdges: [slow], hot: slow }),
      { at: "del", facts: [["目标", `倒数第 ${n} 个`], ["已删除", v[del]]] },
    );
    const ans = a.v.filter((_, i) => i + 1 !== del);
    snap("完成", `返回 dummy.next，结果是 [${ans.join(", ")}]。`, view(), { at: "done", kind: "ok", ans, facts: [["目标", `倒数第 ${n} 个`], ["已删除", v[del]]] });
  }

