build(a, snap) {
      const v = ["D", ...a.v], len = v.length, n = a.n, next = v.map((_, i) => (i + 1 < len ? i + 1 : null));
      const k = {}, calls = []; let del = -1;
      const view = (cur, opts = {}) => [
        {
          t: "list",
          label: "链表（D 是哑节点；虚红线 × 表示断开的旧指针，高亮箭头表示新接上的指针）",
          nodes: v.map((x, i) => ({
            v: x,
            cls: i === del ? (opts.keepWarn ? "w" : "d") : i === cur ? "a" : calls.includes(i) ? "e" : i === 0 ? "d" : "",
            ...(opts.hot === i ? { ecls: "on" } : {}),
            ...(del === i && !opts.keepWarn ? { noNil: true } : {}),
          })),
          next: next.slice(),
          ptrs: Object.fromEntries(Object.entries(k).map(([i, x]) => [`k=${x}`, +i])),
          ...(opts.ghostEdges ? { ghostEdges: opts.ghostEdges } : {}),
          ...(opts.animEdges ? { animEdges: opts.animEdges } : {}),
        },
        { t: "chips", label: "递归调用栈（右边是最里层）", items: calls.map((i) => ({ v: `rec(${v[i]})`, cls: i === cur ? "a" : "e" })), empty: "空" },
      ];
      snap("开始", `从哑节点 D 开始递归。要删的是倒数第 ${n} 个，所以要在回溯时找出倒数第 ${n + 1} 个节点（它的前驱）。`, view(-1), { at: "start", facts: [["目标", `倒数第 ${n} 个`], ["调用栈深度", 0]] });
      for (let i = 0; i < len; i++) {
        const prevDepth = calls.length;
        calls.push(i);
        snap("往下递归", `调用 rec(${v[i]})。它要先等 rec(${i + 1 < len ? v[i + 1] : "空"}) 返回，才知道自己是倒数第几个。`, view(i), { at: "down", facts: [["目标", `倒数第 ${n} 个`], ["调用栈深度", calls.length, prevDepth]] });
      }
      snap("到底", "rec(空) 直接返回 0：空节点后面没有节点。开始往回返回。", view(-1), { at: "base", facts: [["目标", `倒数第 ${n} 个`], ["返回值", 0]] });
      for (let i = len - 1; i >= 0; i--) {
        k[i] = len - i;
        if (k[i] === n + 1) {
          del = i + 1;
          snap(
            "数到 n + 1",
            `rec(${v[i]}) 得到 ${k[i] - 1} + 1 = <b>${k[i]}</b>，正好等于 n + 1！说明 ${v[i]} 后面的 <b>${v[del]}</b> 就是倒数第 ${n} 个。`,
            view(i, { keepWarn: true }),
            { at: "count", kind: "warn", facts: [["目标", `倒数第 ${n} 个`], ["当前倒数 k", k[i], k[i] - 1]] },
          );
          const newNext = del + 1 < len ? del + 1 : null;
          next[i] = newNext;
          next[del] = null;
          snap(
            "删除节点",
            `断开 ${v[i]} → ${v[del]}，把 ${v[i]}.next 改指${newNext === null ? "空（∅）" : ` <b>${v[newNext]}</b>`}，${v[del]} 被删掉。`,
            view(i, { ghostEdges: [[i, del]], animEdges: [i], hot: i }),
            { at: "del", kind: "warn", facts: [["目标", `倒数第 ${n} 个`], ["已删除", v[del]]] },
          );
          snap(
            "返回",
            `rec(${v[i]}) 把自己的编号 ${k[i]} 返回给上一层。`,
            view(i),
            { at: "ret", facts: [["目标", `倒数第 ${n} 个`], ["当前倒数 k", k[i]]] },
          );
        } else {
          snap(
            "返回",
            `rec(${v[i]}) 拿到后面返回的 ${k[i] - 1}，加 1 得 <b>${k[i]}</b>：${i === 0 ? "哑节点 D 也算一个" : `${v[i]} 是倒数第 ${k[i]} 个`}。`,
            view(i),
            { at: ["count", "ret"], facts: [["目标", `倒数第 ${n} 个`], ["当前倒数 k", k[i], k[i] - 1]] },
          );
        }
        calls.pop();
      }
      const ans = a.v.filter((_, i) => i + 1 !== del);
      snap("完成", `递归全部返回，dummy.next 开始的链表就是结果：[${ans.join(", ")}]。`, view(-1), { at: "done", kind: "ok", ans, facts: [["目标", `倒数第 ${n} 个`], ["已删除", v[del]]] });
    }

